package com.tradepilot.survival.entity;
import jakarta.persistence.*;
@Entity @Table(name="next_session_protection_rule_results",uniqueConstraints=@UniqueConstraint(name="uk_protection_rule_result",columnNames={"evaluation_id","rule_type"})) public class NextSessionProtectionRuleResult { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY, optional=false) @JoinColumn(name="evaluation_id", nullable=false) private NextSessionProtectionEvaluation evaluation; @Column(nullable=false,length=48) private String ruleType; @Column(nullable=false,length=32) private String result; @Column(length=120) private String configuredValue; @Column(length=120) private String observedValue; @Column(nullable=false,columnDefinition="text") private String evidence; @Column(nullable=false) private Integer evidenceCount; @Column(nullable=false,length=40) private String calculationVersion; public void setEvaluation(NextSessionProtectionEvaluation v){evaluation=v;} public void setRuleType(String v){ruleType=v;} public void setResult(String v){result=v;} public void setConfiguredValue(String v){configuredValue=v;} public void setObservedValue(String v){observedValue=v;} public void setEvidence(String v){evidence=v;} public void setEvidenceCount(Integer v){evidenceCount=v;} public void setCalculationVersion(String v){calculationVersion=v;} public String getRuleType(){return ruleType;} public String getResult(){return result;} public String getConfiguredValue(){return configuredValue;} public String getObservedValue(){return observedValue;} public String getEvidence(){return evidence;} }
